-- PREPARED ONLY: do not execute on production before explicit approval and a fresh verified backup.
-- Connect SSMS to DESKTOP-AUTD3A3\SQLEXPRESS and select OnlineSalesDb.
SET XACT_ABORT ON;
BEGIN TRY
 BEGIN TRANSACTION;
 IF CAST(SERVERPROPERTY('ServerName') AS nvarchar(128)) <> N'DESKTOP-AUTD3A3\SQLEXPRESS' OR DB_NAME() <> N'OnlineSalesDb'
  THROW 51000, 'Wrong server or database. Nothing applied.', 1;
 IF (SELECT COUNT(*) FROM dbo.__MigrationHistory) <> 2 OR NOT EXISTS
  (SELECT 1 FROM dbo.__MigrationHistory WHERE MigrationId=N'202610151148216_AddShiftManagementTables' AND ContextKey=N'OnlineSalesManagement.Migrations.Configuration')
  THROW 51001, 'Unexpected migration history. Nothing applied.', 1;
 IF COL_LENGTH('dbo.AspNetUsers','IsAdministrativelySuspended') IS NOT NULL OR OBJECT_ID('dbo.AccountAdministrationAudits') IS NOT NULL
  THROW 51002, 'Migration already applied or partial schema exists. Nothing applied.', 1;
CREATE TABLE [dbo].[AccountAdministrationAudits] (
    [Id] [int] NOT NULL IDENTITY,
    [TargetUserId] [nvarchar](128) NOT NULL,
    [ActorUserId] [nvarchar](128) NOT NULL,
    [Action] [nvarchar](20) NOT NULL,
    [Reason] [nvarchar](500) NOT NULL,
    [OccurredUtc] [datetime] NOT NULL,
    CONSTRAINT [PK_dbo.AccountAdministrationAudits] PRIMARY KEY ([Id])
)
ALTER TABLE [dbo].[AspNetUsers] ADD [IsAdministrativelySuspended] [bit] NOT NULL DEFAULT 0
INSERT [dbo].[__MigrationHistory]([MigrationId], [ContextKey], [Model], [ProductVersion])
VALUES (N'202610292211500_AccountGovernance', N'OnlineSalesManagement.Migrations.Configuration',   , N'6.5.1')


 COMMIT TRANSACTION;
END TRY
BEGIN CATCH
 IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
 THROW;
END CATCH;
SELECT MigrationId, ContextKey FROM dbo.__MigrationHistory ORDER BY MigrationId;